"""Live local HTTP E2E. Uses vendor credits and writes labelled test telemetry.

Camera capture is off unless --camera-consent is explicitly supplied. No camera
frames, vital signs, credentials, or vendor error bodies are saved in the report.
"""
import argparse
import base64
import json
import os
from pathlib import Path
import shutil
import socket
import subprocess
import sys
import time
from datetime import datetime, timezone

import httpx

ROOT = Path(__file__).resolve().parents[1]


class E2EFailure(RuntimeError):
    """A credential-safe diagnostic generated by this test harness."""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--camera-consent', action='store_true')
    args = parser.parse_args()
    results = {}
    camera = None
    camera_deadline = None
    flags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
    with socket.socket() as port_socket:
        port_socket.bind(('127.0.0.1', 0))
        port = port_socket.getsockname()[1]
    base = f'http://127.0.0.1:{port}'
    server = subprocess.Popen([sys.executable, '-m', 'uvicorn', 'roboforge.main:app',
                               '--host', '127.0.0.1', '--port', str(port), '--no-access-log'],
                              cwd=ROOT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                              creationflags=flags)

    def record(name, status, **detail):
        results[name] = {'status': status, **detail}
        print(json.dumps({name: results[name]}), flush=True)

    def checked(response):
        response.raise_for_status()
        return response.json()

    def run(name, operation):
        try:
            record(name, 'passed', **(operation() or {}))
        except E2EFailure as error:
            record(name, 'failed', error=str(error))
        except httpx.HTTPStatusError as error:
            # Only app-controlled, sanitized detail from known local endpoints.
            body = error.response.json()
            detail = body.get('detail') if isinstance(body, dict) else None
            record(name, 'failed', http_status=error.response.status_code,
                   error=detail if isinstance(detail, str) else 'Request rejected')
        except Exception as error:
            record(name, 'failed', error_type=type(error).__name__)

    try:
        with httpx.Client(base_url=base, timeout=180, trust_env=False) as client:
            for _ in range(100):
                if server.poll() is not None:
                    raise RuntimeError('Local test server failed to start')
                try:
                    if client.get('/health', timeout=1).status_code == 200:
                        break
                except httpx.RequestError:
                    pass
                time.sleep(0.2)
            else:
                raise RuntimeError('Local test server startup timed out')
            record('backend', 'passed', transport='real localhost HTTP')
            project = checked(client.post('/projects/demo'))
            pid = project['id']
            path = f'/projects/{pid}'
            record('project', 'passed', project_id=pid, revision=project['revision'])
            if args.camera_consent:
                env = {**os.environ, 'ROBOFORGE_API_URL': base}
                camera = subprocess.Popen([shutil.which('node') or 'node', 'bridge.mjs', pid,
                                           '--consent', '--diagnostics', '--duration-seconds=120'],
                                          cwd=ROOT / 'clients/presage', env=env,
                                          stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                          text=True, creationflags=flags)
                camera_deadline = time.monotonic() + 135
                print('Consented SmartSpectra test launched; automatic stop after 120 seconds.', flush=True)

            def finance():
                bom = checked(client.get(path + '/finance/bom'))
                checked(client.get(path + '/finance/budget'))
                checked(client.post(path + '/agents/finance'))
                return {'bom_total_usd': bom['total_usd']}
            run('finance', finance)

            def tiger():
                health = checked(client.get('/integrations/tiger/health'))
                if not health['configured']:
                    raise E2EFailure('TIGER_DATABASE_URL is blank; storage is memory, not Tiger')
                if not health['connected'] or not health['schema_ready']:
                    raise E2EFailure('Tiger connection or schema check failed')
                for value in [10, 20]:
                    checked(client.post(path + '/telemetry', json={'metric': 'battery_pct',
                        'value': value, 'unit': 'percent', 'scenario_id': 'e2e-development'}))
                summary = checked(client.get(path + '/telemetry/summary', params={'scenario_id': 'e2e-development'}))
                points = checked(client.get(path + '/telemetry/timeseries', params={'scenario_id': 'e2e-development'}))
                assert summary['metrics'][0]['samples'] == 2 and summary['metrics'][0]['average'] == 15
                assert sum(point['samples'] for point in points['points']) == 2
                assert all(point['average'] in [10, 15, 20] for point in points['points'])
                return {'samples': 2, 'raw_summary': 'passed', 'minute_rollup': 'passed'}
            run('tiger', tiger)

            def cad():
                part = checked(client.post(path + '/agents/mechanical', json={
                    'spec': {'kind': 'arm_link'}, 'estimated_unit_cost_usd': 8}))
                assert all(part['geometry']['checks'].values())
                for kind, url in part['downloads'].items():
                    response = client.get(url)
                    response.raise_for_status()
                    assert response.content
                    if kind == 'step':
                        assert b'ISO-10303-21' in response.content
                    if kind == 'glb':
                        assert response.content[:4] == b'glTF'
                return {'exports': list(part['downloads']), 'revision': part['revision']}
            run('cad', cad)

            def assembly_prints():
                guide = checked(client.get(path + '/assembly-guide'))
                revision = guide['revision']
                assert guide['protection'] and guide['wiring']['rows'] and guide['buy']
                keys = [s['key'] for s in guide['steps']]
                assert keys.index('wiring') < keys.index('covers') < keys.index('test')
                printable = [p for p in guide['prints'] if p['printable']]
                covers = [p for p in printable if p['kind'] == 'cover']
                assert len(covers) == 2
                files = []
                for cover in covers:
                    for kind in ('stl', 'step'):
                        response = client.get(path + f"/prints/{cover['index']}/{kind}",
                                              params={'revision': revision}, timeout=180)
                        response.raise_for_status()
                        assert len(response.content) > 1000
                        if kind == 'step':
                            assert b'ISO-10303-21' in response.content
                        else:
                            import struct
                            triangles = struct.unpack('<I', response.content[80:84])[0]
                            assert len(response.content) == 84 + 50 * triangles and triangles > 0
                        files.append(f"{cover['name']}.{kind}")
                return {'revision': revision, 'steps': len(guide['steps']),
                        'wiring_routes': len(guide['wiring']['rows']), 'cover_exports': files,
                        'printable_types': len(printable), 'engineering_certified': False}
            run('assembly_prints', assembly_prints)

            def adaptation():
                assert client.post(path + '/adaptive-interface', json={
                    'consent': False, 'state': 'focused', 'confidence': 1}).status_code == 422
                result = checked(client.post(path + '/adaptive-interface', json={
                    'consent': True, 'state': 'needs_guidance', 'confidence': 0.9}))
                assert not result['persisted'] and result['recommendation']['voice_speed'] == 0.85
                return {'consent_gate': 'passed', 'guided_speed': 0.85, 'raw_biometrics_saved': False}
            run('adaptive_interface_contract', adaptation)

            def speech():
                response = client.post('/voice/synthesize', json={
                    'text': 'Hello, I am Forge. What should your robot do?', 'speed': 0.85})
                response.raise_for_status()
                assert response.headers['content-type'].startswith('audio/mpeg')
                audio = response.content
                assert client.post('/voice/transcribe', content=audio,
                                   headers={'content-type': 'audio/mpeg'}).status_code == 422
                transcript = checked(client.post('/voice/transcribe?consent=true', content=audio,
                                                 headers={'content-type': 'audio/mpeg'}))
                assert transcript['text']
                return {'tts_bytes': len(audio), 'stt_text': transcript['text'], 'consent_gate': 'passed'}
            run('elevenlabs', speech)

            def voice():
                before = checked(client.get(path))['revision']
                turn = checked(client.post(path + '/voice/agent', json={
                    'message': 'Introduce yourself in one short sentence. Do not propose CAD.',
                    'interaction': {'consent': True, 'state': 'needs_guidance', 'confidence': 0.9}}))
                assert turn['reply'] and turn['audio'] and not turn['project_changed']
                assert checked(client.get(path))['revision'] == before
                audio = base64.b64decode(turn['audio']['base64'], validate=True)
                turn_audio = checked(client.post(path + '/voice/agent/audio?consent=true', content=audio,
                                                 headers={'content-type': 'audio/mpeg'}))
                assert turn_audio['transcript'] and turn_audio['reply'] and turn_audio['audio']
                return {'text_to_agent_to_speech': 'passed', 'audio_to_agent_to_speech': 'passed',
                        'revision_unchanged': True}
            run('voice_agent_glm', voice)

            def live_voice_session():
                from urllib.parse import urlsplit
                session = checked(client.post('/voice/live/session', json={'project_id': pid}))
                signed = urlsplit(session.get('signed_url', ''))
                assert signed.scheme == 'wss' and signed.hostname == 'api.elevenlabs.io'
                assert session.get('robot_context') and session.get('agent_id')
                # Do not save the signed credential or open a microphone/WebSocket conversation.
                return {'signed_session': 'passed', 'project_context': 'passed',
                        'microphone_opened': False, 'conversation_audio_tested': False}
            run('elevenlabs_live_session', live_voice_session)

            def researched_design():
                designed = checked(client.post('/projects', json={
                    'name': 'You.com researched E2E carrier',
                    'requirements': {'description': 'An indoor wheeled robot that carries 2 kg parcels between office rooms.',
                                     'budget_usd': 2500, 'payload_kg': 2, 'runtime_hours': 2}}))
                design_path = '/projects/' + designed['id']
                result = checked(client.post(design_path + '/design/auto', json={}))
                built = result['project']
                arch = built['architecture']
                research = arch.get('research') or {}
                if research.get('status') != 'ok' or not research.get('references'):
                    raise E2EFailure('No successful live reference search stored with the AI concept')
                if not arch.get('concept'):
                    raise E2EFailure('AI concept fell back to a deterministic design')
                assert built['components']
                assembly = checked(client.get(design_path + '/assembly'))
                assert assembly['nodes']
                guide = checked(client.get(design_path + '/assembly-guide'))
                assert guide
                report = checked(client.get(design_path + '/robot/report', timeout=300))
                assert report['parts'] > 0 and all(d > 0 for d in report['bounds_mm'])
                for kind in ('glb', 'step'):
                    export = client.get(design_path + '/robot/' + kind)
                    export.raise_for_status()
                    if kind == 'glb':
                        assert export.content[:4] == b'glTF'
                    else:
                        assert b'ISO-10303-21' in export.content
                # A budget-only update must keep the concept/research, not trigger another search/model call.
                req = {**built['requirements'], 'budget_usd': 2200}
                rerun = checked(client.post(design_path + '/design/auto', json={'requirements': req}))['project']
                assert rerun['architecture']['concept'] == arch['concept']
                assert rerun['architecture']['research'] == research
                return {'provider': research['provider'], 'references': len(research['references']),
                        'ai_concept': 'passed', 'assembly_nodes': len(assembly['nodes']),
                        'whole_robot_exports': ['glb', 'step', 'report'], 'budget_reuse': 'passed',
                        'project_id': built['id'], 'engineering_certified': False}
            run('researched_robot_design', researched_design)

            if camera:
                try:
                    stdout, _ = camera.communicate(timeout=max(1, camera_deadline - time.monotonic()))
                    summary = None
                    for line in stdout.splitlines():
                        try:
                            data = json.loads(line)
                            if isinstance(data, dict) and 'presageE2E' in data:
                                summary = data['presageE2E']
                        except json.JSONDecodeError:
                            continue
                    if summary is None:
                        record('presage_live', 'failed', exit_code=camera.returncode,
                               error='SDK exited without a diagnostic summary; raw logs withheld')
                    else:
                        record('presage_live', summary.pop('status'), **summary)
                except subprocess.TimeoutExpired:
                    camera.kill()
                    camera.communicate()
                    record('presage_live', 'failed', error='Session exceeded safety timeout; camera process stopped')
            else:
                record('presage_live', 'skipped', reason='No explicit camera consent supplied')
    finally:
        if camera and camera.poll() is None:
            camera.kill()
            camera.communicate()
        server.terminate()
        try:
            server.wait(timeout=10)
        except subprocess.TimeoutExpired:
            server.kill()
            server.wait()
        output = ROOT / 'artifacts/e2e/latest.json'
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text(json.dumps({'run_at': datetime.now(timezone.utc).isoformat(),
                                     'results': results}, indent=2), encoding='utf-8')
        print('Report: ' + str(output), flush=True)
    return 1 if any(item['status'] == 'failed' for item in results.values()) else 0


if __name__ == '__main__':
    raise SystemExit(main())
